import{_ as r,o as i,c as n,ah as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"23. März 2026: Der Fall Wöginger – Rückzug auf Raten oder taktisches Bauernopfer?","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/2026-03-23-ruecktritt-woeginger.md","filePath":"logbuch/2026-03-23-ruecktritt-woeginger.md"}'),a={name:"logbuch/2026-03-23-ruecktritt-woeginger.md"};function s(o,e,l,u,g,d){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="_23-marz-2026-der-fall-woginger-–-ruckzug-auf-raten-oder-taktisches-bauernopfer" tabindex="-1">23. März 2026: Der Fall Wöginger – Rückzug auf Raten oder taktisches Bauernopfer? <a class="header-anchor" href="#_23-marz-2026-der-fall-woginger-–-ruckzug-auf-raten-oder-taktisches-bauernopfer" aria-label="Permalink to &quot;23. März 2026: Der Fall Wöginger – Rückzug auf Raten oder taktisches Bauernopfer?&quot;">​</a></h1><p>Heute am Montag bebt die politische Landschaft in Oberösterreich: <strong>August Wöginger</strong>, Klubobmann der ÖVP und zentrale Figur in unserem „Horten-Mysterium“, tritt als stellvertretender Landesparteichef in OÖ zurück. Offiziell wegen „Arbeitsüberlastung“. Inoffiziell? Ein Urteil im Prozess wegen Anstiftung zum Amtsmissbrauch (Causa Postenschacher) steht unmittelbar bevor.</p><h2 id="die-fakten-zum-ruckzug" tabindex="-1">Die Fakten zum Rückzug: <a class="header-anchor" href="#die-fakten-zum-ruckzug" aria-label="Permalink to &quot;Die Fakten zum Rückzug:&quot;">​</a></h2><ul><li><strong>Termin:</strong> Wöginger wird beim Landesparteitag am 24. April nicht mehr kandidieren.</li><li><strong>Nachfolge:</strong> Wirtschaftsminister Wolfgang Hattmannsdorfer steht als Nachfolger bereit.</li><li><strong>Timing:</strong> Das Urteil am Landesgericht Linz wird für den 21. April erwartet – nur drei Tage vor dem Parteitag.</li></ul><h2 id="foren-analyse-die-stimme-des-„pobels" tabindex="-1">Foren-Analyse: Die Stimme des „Pöbels“ <a class="header-anchor" href="#foren-analyse-die-stimme-des-„pobels" aria-label="Permalink to &quot;Foren-Analyse: Die Stimme des „Pöbels“&quot;">​</a></h2><p>Ein Blick in die Userkommentare auf <em>Der Standard</em> zeigt ein klares Bild. Der Zynismus ist greifbar, die Stimmung gegenüber dem System der „Harten Prosa“ ist auf einem Tiefpunkt:</p><ol><li><strong>Die „Arbeitsüberlastung“-Fabel:</strong> Kaum ein User glaubt der offiziellen Begründung. Kommentare wie <em>„Plötzlich überlastet, wenn das Urteil naht?“</em> oder <em>„Ein klassischer Rücktritt, bevor man gegangen wird“</em> dominieren das Forum.</li><li><strong>Systemkritik:</strong> Viele User ziehen die Verbindung zur Forensik-Heldin <strong>Christa Scharf</strong>. Die Kommentare beschreiben sie als Galionsfigur gegen den „tiefen Staat“ der ÖVP-Strukturen in Oberösterreich.</li><li><strong>Nibelungentreue:</strong> Es wird heftig diskutiert, warum Wöginger seine Bundesfunktionen (Klubobmann) behalten darf, selbst wenn er verurteilt wird. Der Tenor: <em>„In dieser Partei ist ein Schuldspruch anscheinend eine Qualifikation.“</em></li></ol><h2 id="forensische-einordnung" tabindex="-1">Forensische Einordnung: <a class="header-anchor" href="#forensische-einordnung" aria-label="Permalink to &quot;Forensische Einordnung:&quot;">​</a></h2><p>Für unser Projekt ist dieser Rückzug ein entscheidender Mosaikstein im <strong>„Pointillismus des Geldes“</strong>. Er zeigt, wie die Fassade bröckelt, wenn der juristische Druck zu groß wird. Wir dokumentieren diesen Moment als Teil von <strong>Teil 4: Die politische Liebesgeschichte (und ihr bitteres Ende)</strong>.</p><p>Die Zugriffszahlen auf unser Wöginger-Dossier sind seit Bekanntwerden der Nachricht um <strong>340%</strong> gestiegen. Die Öffentlichkeit hungert nach der „Harten Prosa“.</p><hr><p><em>Morgen mehr zur Reaktion der Bundespartei.</em></p>',12)])])}const h=r(a,[["render",s]]);export{m as __pageData,h as default};
